\set ON_ERROR_STOP on
BEGIN;
DO $$
DECLARE admin uuid:=gen_random_uuid(); person uuid:=gen_random_uuid(); attacker uuid:=gen_random_uuid(); existing_user uuid:=gen_random_uuid(); home uuid; other_home uuid; invitation jsonb; invitation2 jsonb; invite_id uuid; member_id uuid; member_aux uuid; new_member uuid; declined_user uuid:=gen_random_uuid(); n integer;
 recipient text:=person||'@test.invalid';
BEGIN
 INSERT INTO auth.users(id,email,email_confirmed_at,raw_user_meta_data) VALUES(admin,admin||'@test.invalid',now(),'{"full_name":"Invitation owner"}'),(attacker,attacker||'@test.invalid',now(),'{"full_name":"Other owner"}'),(existing_user,existing_user||'@test.invalid',now(),'{"full_name":"Existing account"}');
 SELECT household_id INTO STRICT home FROM budget.thousehold_member WHERE user_id=admin;
 SELECT household_id INTO STRICT other_home FROM budget.thousehold_member WHERE user_id=existing_user;
 PERFORM set_config('request.jwt.claim.sub',admin::text,true);
 PERFORM set_config('request.jwt.claim.role','authenticated',true);
 member_id:=public.f_add_household_member(home,'Existing family member','mom');
 SELECT auxiliar_id INTO member_aux FROM budget.thousehold_member WHERE id=member_id;
 INSERT INTO budget.tincome_source(household_id,household_member_id,name,estimated_amount,currency) VALUES(home,member_id,'Preserved salary',500,'BOB');
 INSERT INTO budget.tmember_health_profile(household_member_id,birth_year) VALUES(member_id,1990);
 invitation:=public.f_create_household_invitation(home,recipient,member_id);
 invite_id:=(invitation->>'id')::uuid;
 IF (public.f_household_access(home)->>'admin')<>'true' THEN RAISE EXCEPTION 'Owner access missing'; END IF;
 IF public.f_household_access(home)#>>'{invitations,0,member_id}' IS DISTINCT FROM member_id::text THEN RAISE EXCEPTION 'Invitation not associated with member row'; END IF;
 IF EXISTS(SELECT 1 FROM family_mcp_private.household_invitation WHERE token_hash=invitation->>'token') THEN RAISE EXCEPTION 'Raw token stored'; END IF;
 INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES(person,recipient,'{"full_name":"Invited person"}');
 IF EXISTS(SELECT 1 FROM budget.thousehold_member WHERE user_id=person) THEN RAISE EXCEPTION 'Signup created an extra household'; END IF;
 PERFORM set_config('request.jwt.claim.sub',attacker::text,true);
 IF public.f_inspect_household_invitation(invitation->>'token')->>'status'<>'wrong_email' THEN RAISE EXCEPTION 'Wrong email not detected'; END IF;
 BEGIN PERFORM public.f_accept_household_invitation(invite_id); RAISE EXCEPTION 'Wrong recipient accepted'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Wrong recipient accepted' THEN RAISE; END IF; END;
 PERFORM set_config('request.jwt.claim.sub',person::text,true);
 IF jsonb_array_length(public.f_my_household_invitations())<>1 OR public.f_ensure_my_household() IS NOT NULL THEN RAISE EXCEPTION 'Pending invite not shown or default home created'; END IF;
 BEGIN PERFORM public.f_accept_household_invitation(invite_id); RAISE EXCEPTION 'Unverified email accepted'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Unverified email accepted' THEN RAISE; END IF; END;
 UPDATE auth.users SET email_confirmed_at=now() WHERE id=person;
 IF public.f_accept_household_invitation(invite_id)<>home THEN RAISE EXCEPTION 'Wrong household'; END IF;
 IF public.f_accept_household_invitation(invite_id)<>home THEN RAISE EXCEPTION 'Acceptance replay failed'; END IF;
 SELECT id INTO STRICT new_member FROM budget.thousehold_member WHERE user_id=person AND household_id=home AND status='active';
 IF NOT EXISTS(SELECT 1 FROM budget.thousehold_member WHERE id=new_member AND role='member' AND auxiliar_id=member_aux AND member_type='mom') THEN RAISE EXCEPTION 'Existing auxiliary/relationship not retained'; END IF;
 IF NOT EXISTS(SELECT 1 FROM budget.tincome_source WHERE household_member_id=new_member AND name='Preserved salary') OR NOT EXISTS(SELECT 1 FROM budget.tmember_health_profile WHERE household_member_id=new_member AND birth_year=1990) THEN RAISE EXCEPTION 'Member profile data lost'; END IF;
 IF (SELECT count(*) FROM budget.thousehold_member WHERE user_id=person)<>1 OR EXISTS(SELECT 1 FROM budget.thousehold_member WHERE id=member_id AND status='active') THEN RAISE EXCEPTION 'Duplicate active member'; END IF;
 BEGIN PERFORM public.f_create_household_invitation(home,'another@test.invalid'); RAISE EXCEPTION 'Member invited without admin'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Member invited without admin' THEN RAISE; END IF; END;
 PERFORM public.f_set_my_whatsapp('+19995550201');
 IF public.f_my_whatsapp_verification()->>'verified'<>'false' THEN RAISE EXCEPTION 'Invited member WhatsApp auto-verified'; END IF;
 invitation2:=public.f_begin_whatsapp_verification('+19995550201','es');
 PERFORM set_config('request.jwt.claim.role','service_role',true);
 IF budget.f_messaging_ingress_lab('whatsapp','19995550201',invitation2->>'message','814563555083416')#>>'{verification,verified}'<>'true' THEN RAISE EXCEPTION 'Invited user could not verify WhatsApp'; END IF;
 invitation2:=budget.f_family_mcp('whatsapp','19995550201','transactions','register','{"type":"expense","concept":"Invited member expense","amount":5,"category_key":"clothing_personal_care"}');
 IF invitation2->>'success' IS DISTINCT FROM 'true' OR NOT EXISTS(SELECT 1 FROM budget.ttransaction WHERE household_id=home AND created_by=person AND concept='Invited member expense') THEN RAISE EXCEPTION 'Invited member cannot register expenses: %',invitation2; END IF;
 PERFORM set_config('request.jwt.claim.role','authenticated',true);
 PERFORM set_config('request.jwt.claim.sub',admin::text,true);
 invitation2:=public.f_create_household_invitation(home,existing_user||'@test.invalid');
 PERFORM set_config('request.jwt.claim.sub',existing_user::text,true);
 PERFORM public.f_accept_household_invitation((invitation2->>'id')::uuid);
 IF (SELECT count(*) FROM budget.thousehold_member WHERE user_id=existing_user AND status='active')<>2 OR NOT EXISTS(SELECT 1 FROM budget.thousehold WHERE id=other_home) THEN RAISE EXCEPTION 'Existing household lost'; END IF;
 PERFORM set_config('request.jwt.claim.sub',admin::text,true);
 invitation2:=public.f_create_household_invitation(home,'revoked@test.invalid');
 PERFORM public.f_revoke_household_invitation((invitation2->>'id')::uuid);
 IF public.f_inspect_household_invitation(invitation2->>'token')->>'status'<>'invalid' THEN RAISE EXCEPTION 'Revoked code still valid'; END IF;
 invitation2:=public.f_create_household_invitation(home,'expired@test.invalid');
 UPDATE family_mcp_private.household_invitation SET expires_at=now()-interval '1 second' WHERE id=(invitation2->>'id')::uuid;
 IF public.f_inspect_household_invitation(invitation2->>'token')->>'status'<>'invalid' THEN RAISE EXCEPTION 'Expired code still valid'; END IF;
 invitation2:=public.f_create_household_invitation(home,declined_user||'@test.invalid');
 INSERT INTO auth.users(id,email,email_confirmed_at,raw_user_meta_data) VALUES(declined_user,declined_user||'@test.invalid',now(),'{"full_name":"Declined invitation"}');
 PERFORM set_config('request.jwt.claim.sub',declined_user::text,true);
 PERFORM public.f_decline_household_invitation((invitation2->>'id')::uuid);
 other_home:=public.f_ensure_my_household();
 IF other_home IS NULL OR (SELECT count(*) FROM budget.thousehold_member WHERE user_id=declined_user)<>1 THEN RAISE EXCEPTION 'Declining left user without a household'; END IF;
 IF has_function_privilege('anon','public.f_accept_household_invitation(uuid)','EXECUTE') OR has_table_privilege('authenticated','family_mcp_private.household_invitation','SELECT') THEN RAISE EXCEPTION 'Invitation access exposed'; END IF;
 RAISE NOTICE 'PASS invitations: email proof, no extra signup home, admin-only create, member-only join, existing auxiliar, independent WhatsApp, replay, existing account, expiry/revocation';
END $$;
ROLLBACK;
